@Component("location-handler")
@ProcessingGroup("location-processing-group")
public class LocationEventHandler {
	
	// core constructor
	LocationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateLocationEvent
     */
    @EventHandler
    public void handle( CreateLocationEvent event) {
        entityManager.persist(new Location(event.getLocationId(), event.getLocationCode(), event.getDescription(), event.getWarehouse(), event.getInventoryItems(), event.getLocationType()));
    }

    /*
     * @param	event UpdateLocationEvent
     */
    @EventHandler
    public Location handle( UpdateLocationEvent event) {
    	entityManager.merge(new Location(event.getLocationId(), event.getLocationCode(), event.getDescription(), event.getWarehouse(), event.getInventoryItems(), event.getLocationType()));
    }
    
    /*
     * @param	event DeleteLocationEvent
     */
    @EventHandler
    public void on( DeleteLocationEvent event) {
    	Location entity = new Location();
   
    	// ------------------------------------------
    	// apply the LocationId
    	// ------------------------------------------
    	entity.setLocationId( event.getLocationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final LocationRepository locationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(LocationEventHandler.class.getName());

}
